TEST(WForms, EveryEncodingMatchesTheSpecLayout)
{
    QTemporaryDir dir;
    ASSERT_TRUE(dir.isValid());
    for (const EncodingCase &c : kEncoding)
    {
        std::vector<uint32_t> words;
        try
        {
            words = encode(dir, std::string(".text\n    ") + c.line + "\n");
        }
        catch (const std::exception &error)
        {
            ADD_FAILURE() << c.line << ": did not assemble";
            continue;
        }
        ASSERT_EQ(words.size(), 1u) << c.line;
        EXPECT_EQ(words[0], c.word) << c.line << ": " << hex(words[0], 8) << ", the spec says "
                                    << hex(c.word, 8);
    }
}

TEST(WForms, AShiftImmediateAbove31IsRejected)
{
    // RV64 reserves shamt[5] = 1 for slliw/srliw/sraiw.
    QTemporaryDir dir;
    ASSERT_TRUE(dir.isValid());
    for (const char *line : {"slliw x5, x6, 32", "srliw x5, x6, 63", "sraiw x5, x6, 32"})
        EXPECT_THROW(encode(dir, std::string(".text\n    ") + line + "\n"), std::exception)
            << line << " was accepted";
    EXPECT_NO_THROW(encode(dir, ".text\n    sraiw x5, x6, 31\n"));
}

class WForms : public testing::TestWithParam<IsaParam>
{
};

INSTANTIATE_TEST_SUITE_P(AllModels, WForms, testing::ValuesIn(isaParams(kCases, allModels())),
                         [](const testing::TestParamInfo<IsaParam> &info)
                         { return isaParamName(kCases, info.param); });

TEST_P(WForms, MatchesTheOracle)
{
    QTemporaryDir dir;
    ASSERT_TRUE(dir.isValid());
    expectIsaCase(kCases[GetParam().index], GetParam().model, dir);
}
